declarations.buildNextAptActions:
buildNextAptActions = (g: typeof goLog[number]) => {
    const isAquiSending = aquiSendingId === g.id;
    return [
      {
        k: "here",
        label: isAquiSending ? "GPS…" : t('here'),
        icon: "map-pin" as const,
        color: "#60a5fa",
        fn: async () => {
          if (isAquiSending) return;
          setAquiSendingId(g.id);
          let coords: { lat: number; lng: number } | null = null;
          try {
            const perms = await Location.getForegroundPermissionsAsync();
            let status = perms.status;
            if (status !== "granted" && perms.canAskAgain) {
              const req = await Location.requestForegroundPermissionsAsync();
              status = req.status;
            }
            if (status === "granted") {
              try {
                const last = await Location.getLastKnownPositionAsync({
                  maxAge: 1000 * 60 * 5,
                });
                if (last?.coords) {
                  coords = {
                    lat: last.coords.latitude,
                    lng: last.coords.longitude,
                  };
                }
              } catch {}
              if (!coords) {
                try {
                  const pos = await Location.getCurrentPositionAsync({
                    accuracy: Location.Accuracy.Balanced,
                  });
                  coords = {
                    lat: pos.coords.latitude,
                    lng: pos.coords.longitude,
                  };
                } catch {}
              }
            }
          } catch {}
          const dest = normalizePhoneForWhatsApp(g.phone);
          let txt: string;
          const safeLabel = (g.intentLabel ?? "GO").toUpperCase();
          if (coords) {
            const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${coords.lat},${coords.lng}`;
            txt =
              `📍 Estoy aquí · ${safeLabel}\n${mapsUrl}` +
              (g.place ? `\n(Cita: ${g.place})` : "");
          } else {
            txt =
              `📍 Estoy aquí · ${safeLabel}` +
              (g.place ? ` (${g.place})` : "");
          }
          try {
            const url = dest
              ? `https://wa.me/${dest}?text=${encodeURIComponent(txt)}`
              : `https://wa.me/?text=${encodeURIComponent(txt)}`;
            await Linking.openURL(url);
            showToast(coords ? t('toast_location_sent') : t('toast_alert_no_gps'));
          } catch {
            showToast(t('toast_location_fail'), 'error');
          } finally {
            setAquiSendingId(null);
          }
        },
      },
      {
        k: "late",
        label: t('late'),
        icon: "alert-circle" as const,
        color: "#fde68a",
        fn: () => {
          setLateSheetGo(g);
        },
      },
      {
        k: "snooze",
        label: "+10m",
        icon: "clock" as const,
        color: "#fbbf24",
        fn: () => {
          snoozeGoReminder(g.id, 10);
        },
      },
      {
        k: "change",
        label: t('change'),
        icon: "edit-3" as const,
        color: "#fb923c",
        fn: () => {
          currentReceivedIdRef.current = g.id;
          proposalReturnRef.current = "landing";
          Haptics.selectionAsync();
          setCalOpen(true);
          calFlow.open({
            startAt: "date",
            initialDateISO: g.dateISO || formatISODate(getToday()),
            initialDateDraft: g.date || "",
            initialTime: g.time || "",
            initialDuration: g.duration || "",
            onSave: (r: CalFlowResult) => { sendSuggestChangeFromCal(r); },
            onCancel: () => { setCalOpen(false); },
          });
        },
      },
    ];
  }

declarations.acceptProposal:
acceptProposal = (id: string) => {
    const entry = goLog.find((e) => e.id === id);
    const cp    = entry ? (entry as any).changeProposal : null;

    // ── Anti-solape: comprobar ANTES de aceptar ─────────────────────────────
    if (entry && cp) {
      const conflict = _checkProposalOverlap(
        id,
        cp.dateISO || entry.dateISO,
        cp.time    || entry.time,
        cp.duration !== undefined ? cp.duration : entry.duration,
        goLog,
      );

      if (conflict) {
        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error).catch(() => {});
        // Rechazar la propuesta y restaurar el estado original (sin mover la entrada)
        setGoLog((prev) => {
          const next = prev.map((e) => {
            if (e.id !== id) return e;
            const c = (e as any).changeProposal;
            if (c) {
              return {
                ...e,
                estado: "pendiente" as const,
                dateISO:  c.originalDateISO  || e.dateISO,
                date:     c.originalDate     || e.date,
                time:     c.originalTime     || e.time,
                duration: c.originalDuration !== undefined ? c.originalDuration : e.duration,
                changeProposal: undefined,
                proposal: undefined,
              };
            }
            return { ...e, estado: "pendiente" as const, proposal: undefined };
          });
          persistLog(next);
          return next;
        });
        // Calcular huecos alternativos y mostrarlos
        const alts = findAlternativeGoSlots(entry, goLog);
        setAltSlotsEntry(alts.length > 0 ? { entryId: id, slots: alts } : null);
        // Aviso claro al usuario
        showToast("No disponible por solape en agenda", "error");
        return;
      }
    }

    // ── Sin solape: aceptar normalmente ────────────────────────────────────
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {});
    setGoLog((prev) => {
      const next = prev.map((e) => {
        if (e.id !== id) return e;
        const c = (e as any).changeProposal;
        if (c) {
          return {
            ...e,
            estado: "aceptado" as const,
            dateISO: c.dateISO || e.dateISO,
            date:    c.date    || e.date,
            time:    c.time    || e.time,
            ...(c.duration !== undefined ? { duration: c.duration } : {}),
            ...(c.place ? { place: c.place } : {}),
            changeProposal: undefined,
            proposal: undefined,
          };
        }
        if (!e.proposal) return e;
        const p = e.proposal;
        return {
          ...e,
          estado: "aceptado" as const,
          date:    p.date    || e.date,
          dateISO: p.dateISO || e.dateISO,
          time:    p.time    || e.time,
          duration: p.duration || e.duration,
          place:   p.place   || e.place,
        };
      });
      persistLog(next);
      return next;
    });
    showToast(t('toast_proposal_accepted'), 'success');
  }

declarations.rejectProposal:
rejectProposal = (id: string) => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning).catch(() => {});
    // Calcular alternativas ANTES de modificar el estado (goLog aún tiene el entry original)
    const entry = goLog.find((e) => e.id === id);
    if (entry) {
      const alts = findAlternativeGoSlots(entry, goLog);
      setAltSlotsEntry(alts.length > 0 ? { entryId: id, slots: alts } : null);
    }
    setGoLog((prev) => {
      const next = prev.map((e) => {
        if (e.id !== id) return e;
        const cp = (e as any).changeProposal;
        if (cp) {
          return {
            ...e,
            estado: "pendiente" as const,
            dateISO:  cp.originalDateISO  || e.dateISO,
            date:     cp.originalDate     || e.date,
            time:     cp.originalTime     || e.time,
            duration: cp.originalDuration !== undefined ? cp.originalDuration : e.duration,
            changeProposal: undefined,
            proposal: undefined,
          };
        }
        return { ...e, estado: "pendiente" as const, proposal: undefined };
      });
      persistLog(next);
      return next;
    });
    showToast(t('toast_proposal_rejected'), 'warning');
  }

declarations.setReservationStatus:
setReservationStatus = (bookingId: string, newStatus: ReservationStatus) => {
    LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);

    // Mapa de ReservationStatus → BookingStatus (go_bookings_v1)
    const bkStatusMap: Record<ReservationStatus, BookingStatus> = {
      pendiente:       "HOLD",
      confirmada:      "CONFIRMED",
      cancelada:       "CANCELLED",
      cambio_pendiente:"HOLD",
      completada:      "COMPLETED",
    };
    updateBookingStatus(bookingId, bkStatusMap[newStatus]).catch(() => {});

    if (newStatus === "cancelada") {
      const entry = goLog.find((e) =>
        e.id === `go_booking_cli_${bookingId}` ||
        e.id === `go_booking_prv_${bookingId}` ||
        e.id === `go_booking_${bookingId}`
      );
      if (entry) {
        setCancelSuccessInfo({ label: entry.intentLabel || entry.contactName || "", date: entry.date, time: entry.time });
        setCancelSuccessOpen(true);
        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning).catch(() => {});
      }
    }

    setGoLog((prev) => {
      if (newStatus === "cancelada") {
        const next = cancelAllBookingEntries(bookingId, prev);
        persistLog(next);
        return next;
      }

      const estadoMap: Record<ReservationStatus, GoEstadoT> = {
        pendiente:        "pendiente",
        confirmada:       "aceptado",
        completada:       "aceptado",
        cambio_pendiente: "propuesto",
        cancelada:        "rechazado",
      };

      const relatedIds = new Set([
        `go_booking_cli_${bookingId}`,
        `go_booking_prv_${bookingId}`,
        `go_booking_${bookingId}`,
      ]);
      const next = prev.map((e) =>
        relatedIds.has(e.id)
          ? { ...e, deleted: false, estado: estadoMap[newStatus], bookingStatus: newStatus }
          : e,
      );
      persistLog(next);
      return next;
    });
  }

declarations.sendSuggestChangeFromCal:
sendSuggestChangeFromCal = (calResult: CalFlowResult) => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);

    const id = currentReceivedIdRef.current;
    const returnCtx = proposalReturnRef.current;
    // Always use values from the CalFlowResult — stale app-level drafts are unreliable
    // because calFlow sets isActive=false before calling onSave, preventing the sync
    // useEffects from running.
    const proposedDateISO  = calResult.dateISO;
    const proposedDateDraft = calResult.dateDraft;
    const proposedTime     = calResult.time;
    const durToSave        = calResult.duration || undefined;

    // ── Buscar entrada, validar disponibilidad, persistir y enviar por WhatsApp
    let proposalSent = false;
    if (id) {
      const entry = goLog.find((g) => g.id === id);

      // ── Validar disponibilidad ANTES de persistir ─────────────────────────
      if (entry && proposedTime) {
        const validation = _validateProposalSlot(
          proposedDateISO || entry.dateISO || "",
          proposedTime,
          entry,
        );
        if (!validation.valid) {
          Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error).catch(() => {});
          showToast(validation.reason || "Hora no disponible", "error");
          // Ofrecer huecos alternativos si los hay
          const alts = (() => {
            const durMin = entry.duration ? (
              (() => {
                const hm = entry.duration.match(/^(\d+)h$/i); if (hm) return parseInt(hm[1],10)*60;
                const mm = entry.duration.match(/(\d+)\s*min/i); if (mm) return parseInt(mm[1],10);
                return 60;
              })()
            ) : 60;
            const step = 30;
            const busySlots = goLog
              .filter((e) => e.id !== entry.id && !e.deleted && e.estado !== "rechazado" && e.dateISO === (proposedDateISO || entry.dateISO) && e.time)
              .map((e) => {
                const [hh, mm2] = e.time.split(":").map(Number);
                const s = hh * 60 + (mm2 || 0);
                return { s, end: s + 60 };
              });
            const results: AltSlot[] = [];
            let cur = 8 * 60;
            while (cur + durMin <= 20 * 60 && results.length < 3) {
              if (!busySlots.some((b) => cur < b.end && cur + durMin > b.s)) {
                const h = Math.floor(cur / 60);
                const m = cur % 60;
                const time = `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}`;
                const d = new Date((proposedDateISO || entry.dateISO) + "T00:00:00");
                const WD = ["Dom","Lun","Mar","Mié","Jue","Vie","Sáb"][d.getDay()];
                const dd = String(d.getDate()).padStart(2,"0");
                const mo = String(d.getMonth()+1).padStart(2,"0");
                const date = `${WD} ${dd}/${mo}`;
                results.push({ dateISO: proposedDateISO || entry.dateISO, date, time, label: `Disponible: ${WD} ${d.getDate()} · ${time}` });
              }
              cur += step;
            }
            return results;
          })();
          setAltSlotsEntry(alts.length > 0 ? { entryId: id, slots: alts } : null);
          return; // no persistir, no mover ficha, no enviar WA
        }
      }

      if (entry) {
        const dateStr = proposedDateDraft || proposedDateISO || "";
        const timeStr = proposedTime  ? ` a las ${proposedTime}` : "";
        const durStr  = durToSave  ? `. Duración: ${durToSave}` : "";
        const goLabel = entry.intentLabel ? ` (${entry.intentLabel})` : "";
        const waMsg   = `Te propongo cambiar este GO${goLabel} a: ${dateStr}${timeStr}${durStr}.`;
        proposalSent  = sendProposalViaWhatsApp(entry, waMsg);
      }

      // Persistir propuesta de cambio — mover la ficha al slot propuesto
      // y guardar el slot original en changeProposal para poder restaurarlo.
      const changeProposalPayload = {
        dateISO:   proposedDateISO  || entry?.dateISO || "",
        date:      proposedDateDraft || entry?.date    || "",
        time:      proposedTime      || entry?.time    || "",
        ...(durToSave !== undefined ? { duration: durToSave } : {}),
        note:      suggestNote  || undefined,
        proposedAt: Date.now(),
        originalDateISO:  entry?.dateISO  || "",
        originalDate:     entry?.date     || "",
        originalTime:     entry?.time     || "",
        originalDuration: entry?.duration,
      };
      setGoLog((prev) => {
        const next = prev.map((e) =>
          e.id === id
            ? {
                ...e,
                // propuesta_pendiente = nosotros enviamos la propuesta, esperamos respuesta.
                // propuesto            = la recibimos del otro lado (cliente).
                estado: "propuesta_pendiente" as const,
                // Mover la ficha al slot propuesto para que aparezca en el día correcto.
                dateISO: changeProposalPayload.dateISO || e.dateISO,
                date:    changeProposalPayload.date    || e.date,
                time:    changeProposalPayload.time    || e.time,
                changeProposal: changeProposalPayload,
              }
            : e,
        );
        persistLog(next);
        return next;
      });
      currentReceivedIdRef.current = null;
    }

    // ── Cerrar modos + volver al contexto correcto ─────────────────────────
    calFlow.cancel(); // limpia cualquier estado pendiente de calFlow
    if (returnCtx === "calendar") {
      setClockOpen(false);
      setCalStep("date");
      setCalPanelOpen(false);
    } else if (returnCtx === "list") {
      setCalOpen(false);
      setListOpen(true);
    } else {
      setCalOpen(false);
    }

    // ── Toast de resultado ────────────────────────────────────────────────
    if (proposalSent) {
      showToast(t('toast_proposal_sent_wa'), 'success');
    } else if (id) {
      showToast(t('toast_no_destination_phone'), 'error');
    }
  }

