declarations.buildNextAptActions:
buildNextAptActions = (g: typeof goLog[number]) => {
    const isAquiSending = aquiSendingId === g.id;
    return [
      {
        k: "here",
        label: isAquiSending ? "GPS…" : t('here'),
        icon: "map-pin" as const,
        color: "#60a5fa",
        fn: async () => {
          if (isAquiSending) return;
          setAquiSendingId(g.id);
          let coords: { lat: number; lng: number } | null = null;
          try {
            const perms = await Location.getForegroundPermissionsAsync();
            let status = perms.status;
            if (status !== "granted" && perms.canAskAgain) {
              const req = await Location.requestForegroundPermissionsAsync();
              status = req.status;
            }
            if (status === "granted") {
              try {
                const last = await Location.getLastKnownPositionAsync({
                  maxAge: 1000 * 60 * 5,
                });
                if (last?.coords) {
                  coords = {
                    lat: last.coords.latitude,
                    lng: last.coords.longitude,
                  };
                }
              } catch {}
              if (!coords) {
                try {
                  const pos = await Location.getCurrentPositionAsync({
                    accuracy: Location.Accuracy.Balanced,
                  });
                  coords = {
                    lat: pos.coords.latitude,
                    lng: pos.coords.longitude,
                  };
                } catch {}
              }
            }
          } catch {}
          const dest = normalizePhoneForWhatsApp(g.phone);
          let txt: string;
          const safeLabel = (g.intentLabel ?? "GO").toUpperCase();
          if (coords) {
            const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${coords.lat},${coords.lng}`;
            txt =
              `📍 Estoy aquí · ${safeLabel}\n${mapsUrl}` +
              (g.place ? `\n(Cita: ${g.place})` : "");
          } else {
            txt =
              `📍 Estoy aquí · ${safeLabel}` +
              (g.place ? ` (${g.place})` : "");
          }
          try {
            const url = dest
              ? `https://wa.me/${dest}?text=${encodeURIComponent(txt)}`
              : `https://wa.me/?text=${encodeURIComponent(txt)}`;
            await Linking.openURL(url);
            showToast(coords ? t('toast_location_sent') : t('toast_alert_no_gps'));
          } catch {
            showToast(t('toast_location_fail'), 'error');
          } finally {
            setAquiSendingId(null);
          }
        },
      },
      {
        k: "late",
        label: t('late'),
        icon: "alert-circle" as const,
        color: "#fde68a",
        fn: () => {
          setLateSheetGo(g);
        },
      },
      {
        k: "snooze",
        label: "+10m",
        icon: "clock" as const,
        color: "#fbbf24",
        fn: () => {
          snoozeGoReminder(g.id, 10);
        },
      },
      {
        k: "change",
        label: t('change'),
        icon: "edit-3" as const,
        color: "#fb923c",
        fn: () => {
          currentReceivedIdRef.current = g.id;
          proposalReturnRef.current = "landing";
          Haptics.selectionAsync();
          setCalOpen(true);
          calFlow.open({
            startAt: "date",
            initialDateISO: g.dateISO || formatISODate(getToday()),
            initialDateDraft: g.date || "",
            initialTime: g.time || "",
            initialDuration: g.duration || "",
            onSave: (r: CalFlowResult) => { sendSuggestChangeFromCal(r); },
            onCancel: () => { setCalOpen(false); },
          });
        },
      },
    ];
  }

declarations.renderLandingOperations:
renderLandingOperations = (entry: typeof goLog[number]) => {
    const g = landingCurrentEntry(entry);
    const PANEL_W = landingPanels.region.width;
    const hasPlace = !!(g.place && g.place.trim().length > 0);

    const base = buildNextAptActions(g);
    const aHere = base.find((a) => a.k === "here");
    const aLate = base.find((a) => a.k === "late");
    const aChange = base.find((a) => a.k === "change");

    const aGo = {
      k: "go",
      label: t('go_nav'),
      icon: "navigation" as keyof typeof Feather.glyphMap,
      color: "#60a5fa",
      disabled: !hasPlace,
      fn: () => {
        if (!hasPlace) return;
        Linking.openURL(
          `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(g.place)}`,
        ).catch(() => showToast(t('toast_cannot_open_maps'), 'error'));
      },
    };

    const callPhone  = normalizePhoneForWhatsApp(g.phone || "");
    const hasPhone   = !!(g.phone && callPhone);
    const waRaw      = g.whatsapp || g.phone || "";
    const waPhone    = normalizePhoneForWhatsApp(waRaw);
    const hasWhatsapp = !!waPhone;
    const waMsg = [
      t('whatsapp_intro'),
      resolveIntentLabel(g) || "",
      g.time ? t('at_time').replace('__TIME__', g.time) : "",
    ].filter(Boolean).join(" ");
    const aWA = hasWhatsapp
      ? {
          k: "wa-contact",
          label: "WhatsApp",
          icon: "message-circle" as keyof typeof Feather.glyphMap,
          color: "#4ade80",
          fn: () =>
            Linking.openURL(
              `https://wa.me/${waPhone}?text=${encodeURIComponent(waMsg)}`,
            ).catch(() => showToast(t('toast_wa_open_failed'), 'error')),
        }
      : undefined;
    const aCall = hasPhone
      ? {
          k: "call-contact",
          label: t('call'),
          icon: "phone" as keyof typeof Feather.glyphMap,
          color: "#4ade80",
          fn: () =>
            Linking.openURL(`tel:${callPhone}`).catch(() =>
              showToast(t('toast_call_failed'), 'error'),
            ),
        }
      : undefined;

    const actionGrid = landingActionGrid({ width: landingPanels.region.width,
      leftInset: landingPanelInsets.left, rightInset: landingPanelInsets.right,
      scale: uiScaleFactor, large: uiScale === "grande",
      columns: landingStackTransport ? 2 : hasWhatsapp || hasPhone ? 3 : 2,
      transport: !landingStackTransport, transportWidth: uiScale === "grande" ? 86 : 70 });
    const BTN_H = actionGrid.height;
    const BTN_W = actionGrid.buttonWidth;
    const ACT_ICON = Math.round(16 * uiScaleFactor);
    const ACT_FS   = actionGrid.compressed ? 12 : Math.round(12 * uiScaleFactor);
    const ACT_PV   = Math.round(8  * uiScaleFactor);
    const ACT_PH   = actionGrid.compressed ? 5 : Math.round(8 * uiScaleFactor);
    const ACT_GAP  = Math.round(5  * uiScaleFactor);
    const ACT_BR   = Math.round(12 * uiScaleFactor);
    const ROW_GAP  = Math.round(6  * uiScaleFactor);

    type ActBtnDef = {
      k: string;
      label: string;
      icon: keyof typeof Feather.glyphMap;
      color: string;
      disabled?: boolean;
      fn: () => void;
    };
    const renderActBtn = (a: ActBtnDef) => {
      return (
        <TouchableOpacity
          key={a.k}
          activeOpacity={a.disabled ? 1 : 0.82}
          onPress={() => {
            if (a.disabled) return;
            Haptics.selectionAsync().catch(() => {});
            a.fn();
          }}
          accessibilityLabel={a.label}
          accessibilityState={{ disabled: !!a.disabled }}
          hitSlop={4}
          style={{
            width: BTN_W,
            height: BTN_H,
            borderRadius: Math.round(14 * uiScaleFactor),
            borderWidth: 1,
            borderColor: `${a.color}50`,
            overflow: "hidden",
            shadowColor: a.color,
            shadowOpacity: a.disabled ? 0 : 0.22,
            shadowRadius: 9,
            shadowOffset: { width: 0, height: 1 },
            elevation: 3,
            opacity: a.disabled ? 0.38 : 1,
          }}
