acceptProposal = (id: string) => {
    const entry = goLog.find((e) => e.id === id);
    const cp    = entry ? (entry as any).changeProposal : null;

    // ── Anti-solape: comprobar ANTES de aceptar ─────────────────────────────
    if (entry && cp) {
      const conflict = _checkProposalOverlap(
        id,
        cp.dateISO || entry.dateISO,
        cp.time    || entry.time,
        cp.duration !== undefined ? cp.duration : entry.duration,
        goLog,
      );

      if (conflict) {
        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error).catch(() => {});
        // Rechazar la propuesta y restaurar el estado original (sin mover la entrada)
        setGoLog((prev) => {
          const next = prev.map((e) => {
            if (e.id !== id) return e;
            const c = (e as any).changeProposal;
            if (c) {
              return {
                ...e,
                estado: "pendiente" as const,
                dateISO:  c.originalDateISO  || e.dateISO,
                date:     c.originalDate     || e.date,
                time:     c.originalTime     || e.time,
                duration: c.originalDuration !== undefined ? c.originalDuration : e.duration,
                changeProposal: undefined,
                proposal: undefined,
              };
            }
            return { ...e, estado: "pendiente" as const, proposal: undefined };
          });
          persistLog(next);
          return next;
        });
        // Calcular huecos alternativos y mostrarlos
        const alts = findAlternativeGoSlots(entry, goLog);
        setAltSlotsEntry(alts.length > 0 ? { entryId: id, slots: alts } : null);
        // Aviso claro al usuario
        showToast("No disponible por solape en agenda", "error");
        return;
      }
    }

    // ── Sin solape: aceptar normalmente ────────────────────────────────────
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(() => {});
    setGoLog((prev) => {
      const next = prev.map((e) => {
        if (e.id !== id) return e;
        const c = (e as any).changeProposal;
        if (c) {
          return {
            ...e,
            estado: "aceptado" as const,
            dateISO: c.dateISO || e.dateISO,
            date:    c.date    || e.date,
            time:    c.time    || e.time,
            ...(c.duration !== undefined ? { duration: c.duration } : {}),
            ...(c.place ? { place: c.place } : {}),
            changeProposal: undefined,
            proposal: undefined,
          };
        }
        if (!e.proposal) return e;
        const p = e.proposal;
        return {
          ...e,
          estado: "aceptado" as const,
          date:    p.date    || e.date,
          dateISO: p.dateISO || e.dateISO,
          time:    p.time    || e.time,
          duration: p.duration || e.duration,
          place:   p.place   || e.place,
        };
      });
      persistLog(next);
      return next;
    });
    showToast(t('toast_proposal_accepted'), 'success');
  }

declarations.rejectProposal:
rejectProposal = (id: string) => {
    Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning).catch(() => {});
    // Calcular alternativas ANTES de modificar el estado (goLog aún tiene el entry original)
    const entry = goLog.find((e) => e.id === id);
    if (entry) {
      const alts = findAlternativeGoSlots(entry, goLog);
      setAltSlotsEntry(alts.length > 0 ? { entryId: id, slots: alts } : null);
    }
    setGoLog((prev) => {
      const next = prev.map((e) => {
        if (e.id !== id) return e;
        const cp = (e as any).changeProposal;
        if (cp) {
          return {
            ...e,
            estado: "pendiente" as const,
            dateISO:  cp.originalDateISO  || e.dateISO,
            date:     cp.originalDate     || e.date,
            time:     cp.originalTime     || e.time,
            duration: cp.originalDuration !== undefined ? cp.originalDuration : e.duration,
            changeProposal: undefined,
            proposal: undefined,
          };
        }
        return { ...e, estado: "pendiente" as const, proposal: undefined };
      });
      persistLog(next);
      return next;
    });
    showToast(t('toast_proposal_rejected'), 'warning');
  }

